/**
 * Integration tests for the track/pattern engine (port of MMA/pat*.py).
 *
 * These tests drive the tracks directly, without the parser: a context is
 * built by hand, CTable entries are constructed manually, and the exact
 * MIDI events generated by bar() are compared against golden fixtures
 * produced by the Python oracle (test/tools/gen_track_fixtures.py).
 */

import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { MMAContext } from '../../src/engine/Context';
import { CTable } from '../../src/model/CTable';
import { ChordNotes, type ChordEnv } from '../../src/model/ChordNotes';
import type { Pattern } from '../../src/model/PatternEvent';
import { ArpeggioTrack } from '../../src/model/tracks/ArpeggioTrack';
import { BassTrack } from '../../src/model/tracks/BassTrack';
import { ChordTrack } from '../../src/model/tracks/ChordTrack';
import { DrumTrack } from '../../src/model/tracks/DrumTrack';
import { Melody } from '../../src/model/tracks/MelodyTrack';
import { Solo } from '../../src/model/tracks/SoloTrack';
import { ScaleTrack } from '../../src/model/tracks/ScaleTrack';
import { WalkTrack } from '../../src/model/tracks/WalkTrack';
import { BaseTrack } from '../../src/model/tracks/BaseTrack';
import { trackAlloc } from '../../src/model/tracks/alloc';
import { SwingState } from '../../src/model/features/Swing';
import { harmonize, intervalHarmony } from '../../src/model/features/Harmony';

interface FixtureBar {
  track: 'CHORD' | 'BASS' | 'DRUM' | 'ARPEGGIO' | 'SCALE' | 'WALK' | 'MELODY' | 'SOLO';
  pattern: string;
  chords: string[];
  /** Multiple chords per bar: [chord, start beat, end beat] per bar. */
  chordTabs?: Array<Array<[string, number, number]>>;
  channel: number;
  /** False when run_bar_case() did not assign the channel (setDrumType does). */
  presetChannel?: boolean;
  /** Track setup calls (Python method name + arguments) run before the bars. */
  setup: Array<[string, unknown[]]>;
  /** Optional multiple patterns (TEST1..TESTn) used for the sequence. */
  patterns?: string[] | null;
  /** Set per-track SeqRnd before the bars. */
  seqrnd?: boolean;
  /** RNG seed; both Python's random and MMARandom use CPython MT19937. */
  seed: number | null;
  /** SwingMode arguments (fixtures only use ON and SKEW=nn). */
  swing: string[] | null;
  events: Array<[number, ...string[]]>;
}

/** One HARMONY/HARMONYONLY/HARMONYVOLUME setter run from the oracle. */
interface HarmonySetterCase {
  track: string;
  method: 'setHarmony' | 'setHarmonyOnly' | 'setHarmonyVolume';
  args: string[];
  /** gbl.seqSize used by the Python run. */
  seqsize: number;
  harmony: Array<string | null>;
  harmonyOnly: Array<string | null>;
  harmonyVolume: number[];
  /** warning() messages captured from MMA/harmony.py. */
  warnings: string[];
}

interface Fixture {
  defaults: Record<string, Record<string, unknown>>;
  bars: Record<string, FixtureBar>;
  harmonySetters: Record<string, HarmonySetterCase>;
}

const fixture: Fixture = JSON.parse(
  readFileSync(fileURLToPath(new URL('../fixtures/python/tracks.json', import.meta.url)), 'utf-8'),
);

/** A context set up the way the parser would leave it before a bar. */
function makeContext(): MMAContext {
  const ctx = new MMAContext();
  ctx.tempo = 120;
  ctx.QperBar = 4;
  ctx.barLen = ctx.BperQ * ctx.QperBar;
  ctx.seqSize = 1;
  ctx.seqCount = 0;
  ctx.tickOffset = 0;
  ctx.mtrks.meta().addTempo(0, ctx.tempo);
  ctx.mtrks.meta().addTimeSig(0, 4, 2, 48, 8);
  return ctx;
}

function chordEnv(ctx: MMAContext): ChordEnv {
  return {
    chordList: ctx.chordList,
    cdAdjust: ctx.cdAdjust,
    keyName: () => [ctx.keySig.kName[0], Boolean(ctx.keySig.kName[1])],
    keyNoteValue: () => ctx.keySig.keyNoteValue,
    rep: ctx.rep,
  };
}

function makeCTable(ctx: MMAContext, name: string): CTable {
  const ct = new CTable();
  ct.name = name;
  ct.chord = new ChordNotes(chordEnv(ctx), name);
  ct.chStart = 0;
  ct.chEnd = ctx.barLen;
  return ct;
}

/** Events of a channel as [[tick, hex, ...], ...] (same shape as Python). */
function dumpEvents(ctx: MMAContext, channel: number): Array<[number, ...string[]]> {
  const tr = ctx.mtrks.tracks.get(channel);
  if (!tr) return [];
  const ticks = [...tr.miditrk.keys()].sort((a, b) => a - b);
  return ticks.map(
    (tick) => [tick, ...tr.miditrk.get(tick)!.map((e) => Buffer.from(e).toString('hex'))] as [number, ...string[]],
  );
}

/** Count note-on events on a channel (note-offs use 0x9n velocity 0). */
function countNoteOns(ctx: MMAContext, channel: number): number {
  const tr = ctx.mtrks.tracks.get(channel);
  if (!tr) return 0;
  let n = 0;
  for (const events of tr.miditrk.values()) {
    for (const e of events) if ((e[0]! & 0xf0) === 0x90 && e[2]! > 0) n++;
  }
  return n;
}

function newTrack(ctx: MMAContext, vtype: string): BaseTrack {
  if (vtype === 'CHORD') return new ChordTrack(ctx, vtype);
  if (vtype === 'BASS') return new BassTrack(ctx, vtype);
  if (vtype === 'DRUM') return new DrumTrack(ctx, vtype);
  if (vtype === 'ARPEGGIO') return new ArpeggioTrack(ctx, vtype);
  if (vtype === 'SCALE') return new ScaleTrack(ctx, vtype);
  if (vtype === 'WALK') return new WalkTrack(ctx, vtype);
  if (vtype === 'MELODY') return new Melody(ctx, vtype);
  if (vtype === 'SOLO') return new Solo(ctx, vtype);
  throw new Error(`unknown fixture track ${vtype}`);
}

/** Minimal SwingMode parser covering the fixture's ON / SKEW=nn options. */
function applySwing(ctx: MMAContext, ln: string[]): void {
  const sw = new SwingState();
  for (const opt of ln) {
    const up = opt.toUpperCase();
    if (up === 'ON' || opt === '1') sw.mode = 1;
    else if (up.startsWith('SKEW=')) {
      sw.skew = up.slice(5); // Python keeps the raw option string
      const a = Math.trunc((Number(sw.skew) * ctx.BperQ) / 100);
      ctx.noteLenTable['81'] = a;
      ctx.noteLenTable['82'] = ctx.BperQ - a;
    } else {
      throw new Error(`fixture swing option '${opt}' is not supported`);
    }
  }
  ctx.swingMode = sw;
}

/** Run one bar fixture; mirrors gen_track_fixtures.py run_bar_case(). */
function runBarCase(c: FixtureBar): Array<[number, ...string[]]> {
  const ctx = makeContext();
  ctx.seqSize = c.chordTabs ? c.chordTabs.length : c.chords.length;
  if (c.seed !== null) ctx.rng.seed(c.seed);
  if (c.swing) applySwing(ctx, c.swing);
  const track = newTrack(ctx, c.track);
  // The drum-type case lets setDrumType() assign the channel itself.
  if (c.presetChannel !== false) track.setChannel([String(c.channel)]);
  if (c.patterns) {
    c.patterns.forEach((p, i) => track.definePattern(`TEST${i + 1}`, p));
    track.sequence = c.patterns.map(
      (_, i) => ctx.pats.get(track.vtype, `TEST${i + 1}`) as Pattern,
    );
  } else {
    track.definePattern('TEST', c.pattern);
    track.sequence = [ctx.pats.get(track.vtype, 'TEST') as Pattern];
  }
  track.setSeqSize();
  if (c.seqrnd) track.seqRnd = true;

  for (const [method, args] of c.setup) {
    const fn = (track as unknown as Record<string, (...a: unknown[]) => unknown>)[method];
    if (typeof fn !== 'function') throw new Error(`fixture setup method '${method}' missing on track`);
    fn.apply(track, args);
  }

  if (c.chordTabs) {
    for (let bar = 0; bar < c.chordTabs.length; bar++) {
      ctx.seqCount = bar;
      ctx.tickOffset = bar * ctx.barLen;
      const tabs = c.chordTabs[bar]!.map(([name, start, end]) => {
        const ct = makeCTable(ctx, name);
        ct.chStart = Math.trunc((start - 1) * ctx.BperQ);
        ct.chEnd = Math.trunc((end - 1) * ctx.BperQ);
        return ct;
      });
      track.bar(tabs);
    }
  } else {
    for (let bar = 0; bar < c.chords.length; bar++) {
      ctx.seqCount = bar;
      ctx.tickOffset = bar * ctx.barLen;
      track.bar([makeCTable(ctx, c.chords[bar]!)]);
    }
  }
  return dumpEvents(ctx, track.channel);
}

/** The default state recorded by the Python oracle. */
function trackDefaults(t: BaseTrack): Record<string, unknown> {
  return {
    artic: t.artic,
    chord: t.chord,
    // Python's clearSequence() sets chordLimit = [0, 0]; setChordLimit adds
    // the Force flag as a third entry, so compare the common prefix.
    chordLimit: t.chordLimit.slice(0, 2),
    chordRange: t.chordRange,
    compress: t.compress,
    delay: t.delay,
    direction: t.direction,
    dupRoot: t.dupRoot,
    harmonyVolume: t.harmonyVolume,
    invert: t.invert,
    mallet: t.mallet,
    malletDecay: t.malletDecay,
    octave: t.octave,
    rDuration: t.rDuration,
    rSkip: t.rSkip,
    rSkipBeats: t.rSkipBeats,
    rTime: t.rTime,
    rVolume: t.rVolume,
    seqRnd: t.seqRnd ? 1 : 0,
    seqRndWeight: t.seqRndWeight,
    sequence: t.sequence,
    spanEnd: t.spanEnd,
    spanStart: t.spanStart,
    strum: t.strum,
    strumAdd: t.strumAdd,
    toneList: t.vtype === 'DRUM' || t.vtype === 'MELODY' || t.vtype === 'SOLO' ? t.toneList : null,
    unify: t.unify,
    voice: t.voice,
    volume: t.volume,
    stretch: 'stretch' in t ? (t as Melody).stretch : null,
    followChord: 'followChord' in t ? (t as Melody).followChord : null,
    followKey: 'followKey' in t ? (t as Melody).followKey : null,
    rootChord: 'rootChord' in t ? (t as Melody).rootChord : null,
    drumType: 'drumType' in t ? (t as Melody).drumType : null,
  };
}

describe('track defaults after clearSequence', () => {
  for (const vtype of ['CHORD', 'BASS', 'DRUM', 'ARPEGGIO', 'SCALE', 'WALK', 'MELODY', 'SOLO']) {
    it(`${vtype} matches the Python defaults`, () => {
      const ctx = makeContext();
      const track = newTrack(ctx, vtype);
      expect(trackDefaults(track)).toEqual(fixture.defaults[vtype]);
    });
  }
});

describe('bar() output vs Python fixtures', () => {
  for (const [name, c] of Object.entries(fixture.bars)) {
    it(`${name} produces identical MIDI events`, () => {
      expect(runBarCase(c)).toEqual(c.events);
    });
  }

  it('covers all eight ported track types', () => {
    const types = new Set(Object.values(fixture.bars).map((b) => b.track));
    expect(types).toEqual(
      new Set(['CHORD', 'BASS', 'DRUM', 'ARPEGGIO', 'SCALE', 'WALK', 'MELODY', 'SOLO']),
    );
  });
});

describe('sequence size', () => {
  it('expands all per-sequence lists', () => {
    const ctx = makeContext();
    ctx.seqSize = 1;
    const track = new BassTrack(ctx, 'BASS');
    track.definePattern('P1', '1 4 1 90');
    const p1 = ctx.pats.get('BASS', 'P1') as Pattern;
    track.sequence = [p1];

    ctx.seqSize = 4;
    track.setSeqSize();

    expect(track.sequence).toEqual([p1, p1, p1, p1]);
    expect(track.octave).toEqual([48, 48, 48, 48]);
    expect(track.volume).toEqual([1, 1, 1, 1]);
    expect(track.voice).toEqual([0, 0, 0, 0]);
    expect(track.artic).toEqual([90, 90, 90, 90]);
    expect(track.invert).toEqual([[], [], [], []]);
    expect(track.accent).toEqual([[], [], [], []]);
    expect(track.delay).toEqual([0, 0, 0, 0]);
    expect(track.seqRndWeight).toEqual([1, 1, 1, 1]);
  });

  it('contracts to the new size', () => {
    const ctx = makeContext();
    ctx.seqSize = 1;
    const track = new BassTrack(ctx, 'BASS');
    ctx.seqSize = 3;
    track.setSeqSize();
    expect(track.octave).toHaveLength(3);

    ctx.seqSize = 1;
    track.setSeqSize();
    expect(track.octave).toEqual([48]);
    expect(track.rTime).toEqual([[0, 0]]);
  });
});

describe('setVoice / setOctave / setVolume list semantics', () => {
  it('decodes voice names per sequence slot', () => {
    const ctx = makeContext();
    ctx.seqSize = 2;
    const track = new BassTrack(ctx, 'BASS');
    track.setVoice(['Piano1', 'Flute']);
    expect(track.voice).toEqual([0, 73]);
  });

  it('accepts extended voice values', () => {
    const ctx = makeContext();
    const track = new BassTrack(ctx, 'BASS');
    // Extended value Prog.MSB.LSB; Python packs LSB in the high bits.
    track.setVoice(['10.3.2']);
    expect(track.voice).toEqual([(2 << 16) + (3 << 8) + 10]);
  });

  it('sets octaves absolutely and relatively', () => {
    const ctx = makeContext();
    ctx.seqSize = 2;
    const track = new BassTrack(ctx, 'BASS');
    track.setOctave(['3', '5']);
    expect(track.octave).toEqual([36, 60]);

    // Slot 0 is still octave 3 (36); +/- adjusts the existing value.
    ctx.seqSize = 1;
    track.setOctave(['+1']);
    expect(track.octave).toEqual([48]);
    track.setOctave(['-1']);
    expect(track.octave).toEqual([36]);
  });

  it('sets volumes from mnemonics and percentages', () => {
    const ctx = makeContext();
    ctx.seqSize = 2;
    const track = new BassTrack(ctx, 'BASS');
    track.setVolume(['pp', 'ff']);
    expect(track.volume).toEqual([0.25, 1.6]);

    ctx.seqSize = 1;
    const fresh = new BassTrack(ctx, 'BASS-2');
    fresh.setVolume(['50%']);
    expect(fresh.volume).toEqual([0.5]);
  });

  it('sets strum pairs and clears them with 0,0', () => {
    const ctx = makeContext();
    ctx.seqSize = 2;
    const track = new ChordTrack(ctx, 'CHORD');
    track.setStrum(['20', '10,30']);
    expect(track.strum).toEqual([
      [20, 20],
      [10, 30],
    ]);
    ctx.seqSize = 1;
    track.setStrum(['0,0']);
    expect(track.strum).toEqual([null]);
  });
});

describe('grooves', () => {
  it('saveGroove/restoreGroove round-trips track settings', () => {
    const ctx = makeContext();
    ctx.seqSize = 2;
    const track = new ChordTrack(ctx, 'CHORD');
    track.setChannel(['5']);
    track.definePattern('P1', '1 4 90');
    const p1 = ctx.pats.get('CHORD', 'P1') as Pattern;
    track.sequence = [p1, null];
    track.setVolume(['ff']);
    track.setOctave(['3']);
    track.setStrum(['20']);
    track.setDupRoot(['1,-1']);
    track.setChordLimit(['4', 'DROP=2', 'FORCE=TRUE']);
    track.setVoicing(['MODE=DROP2']);

    track.saveGroove('G1');
    const seqBefore = [...track.sequence];
    const dupBefore = track.dupRoot.map((x) => [...x]);

    // Mangle everything the groove covers.
    track.sequence = [null, null];
    track.setVolume(['pp']);
    track.setOctave(['9']);
    track.strum = [null];
    track.dupRoot = [[]];
    track.chordLimit = [0, 0, false];
    track.setVoicing(['MODE=NONE']);

    track.restoreGroove('G1');

    expect(track.sequence).toEqual(seqBefore);
    expect(track.volume).toEqual([1.6, 1.6]);
    expect(track.octave).toEqual([36, 36]);
    expect(track.strum).toEqual([
      [20, 20],
      [20, 20],
    ]);
    expect(track.dupRoot).toEqual(dupBefore);
    expect(track.chordLimit).toEqual([4, 2, true]);
    expect(track.voicing?.mode).toBe('DROP2');
  });

  it('errors when the groove has no data for the track', () => {
    const ctx = makeContext();
    const track = new BassTrack(ctx, 'BASS');
    expect(() => track.restoreGroove('NOPE')).toThrow(/no groove data/);
  });

  it('allocates newly created tracks into existing grooves', () => {
    const ctx = makeContext();
    const bass = new BassTrack(ctx, 'BASS');
    ctx.tnames.set('BASS', bass);
    ctx.grooves.defineDo(ctx, 'G1');

    const drum = trackAlloc(ctx, 'DRUM', true) as DrumTrack;
    // The new track captured the current defaults into the groove.
    drum.setTone(['SnareDrum1']);
    drum.restoreGroove('G1');
    expect(drum.toneList).toEqual([38]);
  });
});

describe('track allocation', () => {
  it('splits NAME-EXT at the first dash and reuses base classes', () => {
    const ctx = makeContext();
    const a = trackAlloc(ctx, 'BASS-FOO', true);
    expect(a).toBeInstanceOf(BassTrack);
    expect(ctx.tnames.get('BASS-FOO')).toBe(a);
    expect(trackAlloc(ctx, 'BASS-FOO', true)).toBe(a);

    const b = trackAlloc(ctx, 'DRUM-3', true);
    expect(b).toBeInstanceOf(DrumTrack);
    expect(b!.channel).toBe(10);
  });

  it('returns undefined (err=false) or errors (err=true) for unknown names', () => {
    const ctx = makeContext();
    expect(trackAlloc(ctx, 'NOPE', false)).toBeUndefined();
    expect(() => trackAlloc(ctx, 'NOPE', true)).toThrow(/no track class/);
  });

  it('allocates the M2 tracks with their real classes', () => {
    const ctx = makeContext();
    expect(trackAlloc(ctx, 'WALK', true)).toBeInstanceOf(WalkTrack);
    expect(trackAlloc(ctx, 'ARPEGGIO', true)).toBeInstanceOf(ArpeggioTrack);
    expect(trackAlloc(ctx, 'SCALE', true)).toBeInstanceOf(ScaleTrack);
  });

  it('allocates the ported SOLO/MELODY tracks and stubs the rest', () => {
    const ctx = makeContext();
    expect(trackAlloc(ctx, 'SOLO', true)).toBeDefined();
    expect(trackAlloc(ctx, 'MELODY', true)).toBeDefined();
    expect(() => trackAlloc(ctx, 'PLECTRUM', true)).toThrow(/M2/);
    expect(() => trackAlloc(ctx, 'ARIA', true)).toThrow(/M2/);
  });

  it('ChShare copies the channel and voice from the shared track', () => {
    const ctx = makeContext();
    const bass = new BassTrack(ctx, 'BASS');
    bass.setChannel(['3']);
    ctx.tnames.set('BASS', bass);

    const chord = new ChordTrack(ctx, 'CHORD');
    ctx.tnames.set('CHORD', chord);
    chord.setChShare('BASS');

    expect(chord.channel).toBe(3);
    expect(ctx.midiAvail[3]).toBe(2);
    expect(ctx.midiAssigns[3]).toEqual(['BASS', 'CHORD']);
    expect(chord.voice).toEqual(bass.voice);
  });

  it('auto-assigns the highest free channel, skipping 10', () => {
    const ctx = makeContext();
    const track = new BassTrack(ctx, 'BASS');
    track.setChannel();
    expect(track.channel).toBe(16);
    expect(ctx.midiAvail[16]).toBe(1);

    const track2 = new BassTrack(ctx, 'BASS-2');
    track2.setChannel();
    expect(track2.channel).toBe(15);
  });
});

describe('pattern definition', () => {
  it('accepts token lists as well as pattern strings', () => {
    const ctx = makeContext();
    const track = new BassTrack(ctx, 'BASS');
    track.definePattern('P1', ['1', '4', '1', '90']);
    const pat = ctx.pats.get('BASS', 'P1') as Pattern;
    expect(pat).toHaveLength(1);
    expect(pat[0]!.offset).toBe(0);
    expect(pat[0]!.duration).toBe(192);
  });

  it('applies * and SHIFT modifiers like Python', () => {
    const ctx = makeContext();
    const track = new DrumTrack(ctx, 'DRUM');
    track.definePattern('D1', '1 4 90 * 2');
    const pat = ctx.pats.get('DRUM', 'D1') as Pattern;
    // Python's mulPatRiff: offset = offset // fact + n * (barLen // fact).
    expect(pat.map((p) => p.offset)).toEqual([0, 384]);
    expect(pat.map((p) => p.duration)).toEqual([96, 96]);
  });

  it('formats patterns for display', () => {
    const ctx = makeContext();
    const bass = new BassTrack(ctx, 'BASS');
    bass.definePattern('P1', '1 4 1 90');
    expect(bass.formatPattern(ctx.pats.get('BASS', 'P1') as Pattern)).toBe('1 192t 1 90');

    const drum = new DrumTrack(ctx, 'DRUM');
    drum.definePattern('D1', '1 4 90');
    expect(drum.formatPattern(ctx.pats.get('DRUM', 'D1') as Pattern)).toBe('1 192t 90 ');

    // Chord patterns print all 8 forced volumes, as in Python.
    const chord = new ChordTrack(ctx, 'CHORD');
    chord.definePattern('C1', '1 4 90');
    expect(chord.formatPattern(ctx.pats.get('CHORD', 'C1') as Pattern)).toBe(
      '1 192t 90 90 90 90 90 90 90 90',
    );
  });

  it('stores track-specific chords lines', () => {
    const ctx = makeContext();
    const track = new BassTrack(ctx, 'BASS');
    track.setChords(['C', 'F']);
    expect(track.chord).toEqual([['C', 'F']]);
    // With seqSize 1 the list is truncated; grow the sequence first.
    ctx.seqSize = 3;
    track.setChords(['{C}', '/', '{F}']);
    expect(track.chord).toEqual([['C'], ['C'], ['F']]);
  });
});

describe('ARPEGGIO / SCALE / WALK track state', () => {
  it('arpeggio restart resets the run position only', () => {
    const ctx = makeContext();
    const track = new ArpeggioTrack(ctx, 'ARPEGGIO');
    track.arpOffset = 5;
    track.arpDirection = -1;
    track.lastRange = 2;
    track.lastDirection = 'UP';
    track.restart();
    expect(track.arpOffset).toBe(-1);
    expect(track.arpDirection).toBe(1);
    // Python's restart() assigns to locals for these two (no self.), so
    // the previous values survive; reproduced deliberately.
    expect(track.lastRange).toBe(2);
    expect(track.lastDirection).toBe('UP');
  });

  it('scale setScaletype validates and stores the scale types', () => {
    const ctx = makeContext();
    ctx.seqSize = 2;
    const track = new ScaleTrack(ctx, 'SCALE');
    track.setScaletype(['chromatic', 'chord']);
    expect(track.scaleType).toEqual(['CHROMATIC', 'CHORD']);
    expect(() => track.setScaletype(['NOPE'])).toThrow(/Only Chromatic/);
  });

  it('scale setDirection resets the run state', () => {
    const ctx = makeContext();
    const track = new ScaleTrack(ctx, 'SCALE');
    track.lastNote = 60;
    track.scaleLastChord = 'CM';
    track.setDirection(['DOWN']);
    expect(track.direction).toEqual(['DOWN']);
    expect(track.lastNote).toBe(-1);
    expect(track.scaleLastChord).toBeNull();
  });

  it('scale restart clears all run state', () => {
    const ctx = makeContext();
    const track = new ScaleTrack(ctx, 'SCALE');
    track.lastNote = 60;
    track.scaleLastChord = 'CM';
    track.lastStype = 'SCALE';
    track.lastDirect = 1;
    track.lastRange = 2;
    track.sOffset = 3;
    track.notes = [1, 2, 3];
    track.dirfact = -1;
    track.restart();
    expect(track.lastNote).toBe(-1);
    expect(track.scaleLastChord).toBeNull();
    expect(track.lastStype).toBeNull();
    expect(track.lastDirect).toBe(1);
    expect(track.lastRange).toBe(0);
    expect(track.sOffset).toBe(0);
    expect(track.notes).toBeNull();
    expect(track.dirfact).toBe(1);
  });

  it('walk restart resets the direction pointer', () => {
    const ctx = makeContext();
    const track = new WalkTrack(ctx, 'WALK');
    track.walkChoice = 4;
    track.restart();
    expect(track.walkChoice).toBe(0);
  });

  it('HARMONY adds chord-derived notes on the M2 tracks', () => {
    for (const vtype of ['ARPEGGIO', 'SCALE', 'WALK']) {
      const ctx = makeContext();
      const track = newTrack(ctx, vtype);
      track.definePattern('P1', '1 4 90');
      track.sequence = [ctx.pats.get(vtype, 'P1') as Pattern];
      track.setHarmony(['3']);
      track.bar([makeCTable(ctx, 'C')]);
      // The pattern note plus the two '3' harmony notes; the byte-exact
      // event streams are covered by the fixture bars.
      expect(countNoteOns(ctx, track.channel)).toBe(3);
    }
  });

  it('ORNAMENT playback on SCALE needs the unported ornament module', () => {
    const ctx = makeContext();
    const track = new ScaleTrack(ctx, 'SCALE');
    track.definePattern('P1', '1 4 90');
    track.sequence = [ctx.pats.get('SCALE', 'P1') as Pattern];
    track.ornaments.type = 'GRACE';
    expect(() => track.bar([makeCTable(ctx, 'C')])).toThrow(/M2.*ornament/);
  });
});

describe('M2 stubs for unported features', () => {
  it('track-specific CHORDS need the unported parseChordLine', () => {
    const ctx = makeContext();
    const track = new BassTrack(ctx, 'BASS');
    track.definePattern('P1', '1 4 1 90');
    track.sequence = [ctx.pats.get('BASS', 'P1') as Pattern];
    track.setChords(['C']);
    expect(() => track.bar([makeCTable(ctx, 'G')])).toThrow(/M2.*parseChordLine/);
  });

  it('ORNAMENT playback needs the unported ornament module', () => {
    const ctx = makeContext();
    const track = new ChordTrack(ctx, 'CHORD');
    track.definePattern('P1', '1 4 90');
    track.sequence = [ctx.pats.get('CHORD', 'P1') as Pattern];
    track.ornaments.type = 'GRACE';
    expect(() => track.bar([makeCTable(ctx, 'C')])).toThrow(/M2.*ornament/);
  });

  it('TRIGGER sequences need the unported trigger module', () => {
    const ctx = makeContext();
    const track = new BassTrack(ctx, 'BASS');
    track.definePattern('P1', '1 4 1 90');
    track.sequence = [ctx.pats.get('BASS', 'P1') as Pattern];
    track.trigger.mode = 'BEATS';
    expect(() => track.bar([makeCTable(ctx, 'C')])).toThrow(/M2.*TRIGGER/);
  });
});

